{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "A close structural analogue, a 2-methyltryptamine amide with an aryl-heterocycle, was measured in vivo in mice to cross the BBB with a brain-to-plasma ratio of 0.16 and was classified as permeable, directly supporting CNS access for the query's similar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A lipophilic N-alkyl tryptamine reached 21.8 ng/mL in mouse brain after oral administration, demonstrating that tryptamine derivatives with substantial lipophilic substitution can achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Tropisetron, an indole-containing drug with an ester/amide-like linker, achieved a brain/plasma ratio of 2.5 in mice, showing high brain permeability for indole-based compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Tryptophan, the parent amino acid of the tryptamine core, is confirmed by human PET to cross the BBB, supporting the indole-ethylamine motif's CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Histidine, containing the imidazole ring present in the query, readily crosses the BBB and increases brain levels after systemic administration, supporting CNS access for the imidazole-containing query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple high-transfer experimental records, including a close 2-methyltryptamine amide analogue with measured brain penetration, support meaningful CNS access for the query.",
  "evidence_gaps": [
    "No direct human or rodent brain/plasma or CSF measurement for the exact query molecule.",
    "No explicit efflux-transporter data for the query, although the close analogue C04 was still classified as permeable.",
    "Unbound brain concentrations are not available, so the degree of functional CNS exposure is not fully quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

